const body = $input.item.json.body || $input.item.json;

// Get the unique vehicle ID from the Zoho Forms submission
const vehicleId = String(
  body.FahrzeugID ||
  body.SingleLine ||
  body.SingleLine1 ||
  ""
).trim();

if (!vehicleId) {
  throw new Error("FahrzeugID is missing from the form submission.");
}

// Get the five submitted vehicle details
const jahresfahrleistung = String(
  body.Jahresfahrleistung ||
  body.Dropdown ||
  ""
).trim();

const kilometerstand = parseInt(
  body.Kilometerstand ||
  body.Number ||
  "0",
  10
);

const stellplatz = String(
  body.Stellplatz ||
  body.Dropdown1 ||
  ""
).trim();

const nutzung = String(
  body.Nutzung ||
  body.Dropdown2 ||
  ""
).trim();

const selbstbeteiligung = parseFloat(
  body.Selbstbeteiligung ||
  body.Number1 ||
  "0"
);

return [
  {
    json: {
      vehicleId,
      jahresfahrleistung,
      kilometerstand,
      stellplatz,
      nutzung,
      selbstbeteiligung,
      submittedAt: new Date().toISOString()
    }
  }
];

